        SENTINEL_ORACLE().setTokenOracleConfig(token, address(CURVE_ORACLE));
        DEVIATION_SENTINEL().setTokenConfig(
            token,
            IDeviationSentinel.TokenConfig({ deviation: DEVIATION_PERCENT, enabled: true })
